import Foundation
import Combine

/// One saved AI chat conversation's metadata — what the session list (the
/// chat panel's ☰ menu) shows without loading the transcript itself.
/// `title` is empty until the first message names the chat (see
/// `AIChatSessionStore.fallbackTitle`) or the user renames it.
struct ChatSessionSummary: Codable, Identifiable, Equatable {
    var id: UUID
    var title: String
    /// True while the title came from the fallback/LLM naming rather than a
    /// user rename — only auto-generated titles get replaced by the model.
    var titleIsAutoGenerated: Bool
    var createdAt: Date
    var updatedAt: Date
    var messageCount: Int

    init(id: UUID, title: String, titleIsAutoGenerated: Bool, createdAt: Date, updatedAt: Date, messageCount: Int) {
        self.id = id
        self.title = title
        self.titleIsAutoGenerated = titleIsAutoGenerated
        self.createdAt = createdAt
        self.updatedAt = updatedAt
        self.messageCount = messageCount
    }

    init(record: ChatSessionRecord) {
        self.init(
            id: record.id,
            title: record.title,
            titleIsAutoGenerated: record.titleIsAutoGenerated,
            createdAt: record.createdAt,
            updatedAt: record.updatedAt,
            messageCount: record.messages.count
        )
    }

    /// What the session menu shows for an unnamed chat.
    var displayTitle: String { title.isEmpty ? "Untitled chat" : title }
}

/// The full on-disk form of one conversation: the summary fields plus the
/// whole transcript. One JSON file per session, next to an `index.json`
/// listing the summaries, so the session menu loads instantly no matter how
/// many (or how large) the conversations are.
struct ChatSessionRecord: Codable, Equatable {
    var id: UUID
    var title: String
    var titleIsAutoGenerated: Bool
    var createdAt: Date
    var updatedAt: Date
    var messages: [ChatMessage]
}

enum ChatSessionImportError: LocalizedError {
    case unrecognizedFormat

    var errorDescription: String? {
        switch self {
        case .unrecognizedFormat:
            return "This file isn't a TypstEdit chat export (expected a conversation JSON or a chat history file)."
        }
    }
}

/// Owns the AI chat's conversations: the session list for the current scope
/// (project folder or notebook), the live `AIChatManager` instance behind
/// each session, and which one the panel currently shows.
///
/// Every conversation is its own manager, so each keeps its own generation
/// task, pending approval, and tool state — that's what lets one chat keep
/// working in the background while the user switches to another one. Each
/// manager reports transcript changes back here (`chatSessionDidUpdate`),
/// which is where saving happens: the session file and the index are rewritten
/// atomically on every change, the same write-per-change pattern the old
/// single `history.json` used.
///
/// Storage layout (when saving is on):
/// - project:  `<root>/.typstedit/chat/sessions/index.json` + `<uuid>.json`
/// - notebook: `~/Library/Application Support/TypstEdit/ChatHistory/<hash>/sessions/…`
/// - standalone file: nowhere — sessions live in memory for this run only
/// A legacy single `history.json` (or notebook `<hash>.json`) is imported as
/// one session the first time its scope is opened.
@MainActor
final class AIChatSessionStore: ObservableObject {
    static let shared = AIChatSessionStore()

    /// Sessions for the current scope, most recently active first. Includes
    /// in-memory-only sessions (standalone scope, or saving turned off).
    @Published private(set) var sessions: [ChatSessionSummary] = []
    @Published private(set) var activeSessionID: UUID?
    /// The conversation the chat panel shows. Never nil — a fresh empty
    /// session is created whenever there's nothing to select.
    @Published private(set) var activeManager: AIChatManager

    /// Live managers, keyed by session ID. A manager stays here (and keeps
    /// generating) for the whole app run once loaded, even after its scope
    /// changes... except on a scope switch, where managers of the old scope
    /// are stopped and dropped: their file tools point at a folder that is
    /// no longer open.
    private var managers: [UUID: AIChatManager] = [:]
    private var scope: LocalToolExecutor.Scope = .none
    private var currentProjectRoot: URL?
    private var currentFileURL: URL?

    private init() {
        let manager = AIChatManager()
        managers[manager.id] = manager
        activeManager = manager
        activeSessionID = manager.id
        // All stored properties are set, so self can be shared now — the
        // same wiring `register(_:)` does for every later manager.
        manager.sessionStore = self
    }

    /// Ownership + the callback wiring: the manager is kept alive here and
    /// its `persist()` calls land in `chatSessionDidUpdate`.
    private func register(_ manager: AIChatManager) {
        manager.sessionStore = self
        managers[manager.id] = manager
    }

    // MARK: - Context (called by `EditorController` and the chat panel)

    /// Forwards the open project/file to the active conversation, and handles
    /// the rare scope switch (a different project or notebook was opened) by
    /// swapping the whole session list over.
    func updateContext(projectRoot: URL?, currentFileURL: URL?) {
        self.currentProjectRoot = projectRoot
        self.currentFileURL = currentFileURL
        let newScope = AIChatManager.resolveScope(projectRoot: projectRoot, currentFileURL: currentFileURL)
        guard newScope != scope else {
            activeManager.updateContext(projectRoot: projectRoot, currentFileURL: currentFileURL)
            return
        }

        // Anything still running against the outgoing scope gets stopped —
        // its file tools point at a folder that's no longer open (this also
        // denies a pending approval, as the old single-transcript switch did).
        for manager in managers.values where manager.isGenerating {
            manager.stop()
        }
        managers.removeAll()
        scope = newScope
        migrateLegacyIfNeeded()
        sessions = Self.loadIndex(from: recordDirectory.map(Self.indexURL(in:)))

        if let latest = sessions.first {
            activate(latest.id)
        } else {
            startNewSession()
        }
        activeManager.updateContext(projectRoot: projectRoot, currentFileURL: currentFileURL)
    }

    // MARK: - Session Actions (called from the chat panel)

    /// Starts a fresh, empty conversation and shows it. Nothing is written
    /// to disk until it gets its first message (or a name).
    func startNewSession() {
        let manager = AIChatManager(scope: scope)
        register(manager)
        activeManager = manager
        activeSessionID = manager.id
    }

    /// Shows a different conversation; the previous one stays exactly as it
    /// is — including any generation it still has running.
    func switchSession(to id: UUID) {
        guard id != activeSessionID, sessions.contains(where: { $0.id == id }) else { return }
        activate(id)
        activeManager.updateContext(projectRoot: currentProjectRoot, currentFileURL: currentFileURL)
    }

    func renameSession(_ id: UUID, to rawTitle: String) {
        managers[id]?.rename(to: rawTitle)
    }

    /// Wipes a conversation's transcript and removes its saved file. The
    /// session slot itself stays (it becomes a fresh, unnamed chat) — the
    /// panel's trash button.
    func clearSession(_ id: UUID) {
        guard let manager = managers[id] else { return }
        manager.clearHistory()
    }

    func deleteSession(_ id: UUID) {
        managers[id]?.stop()
        managers[id] = nil
        sessions.removeAll { $0.id == id }
        deleteRecord(id: id)
        guard activeSessionID == id else { return }
        if let latest = sessions.first {
            activate(latest.id)
        } else {
            startNewSession()
        }
        activeManager.updateContext(projectRoot: currentProjectRoot, currentFileURL: currentFileURL)
    }

    /// Imports a conversation export (or a legacy `history.json`) as a new
    /// session in the current scope and shows it.
    @discardableResult
    func importSession(from url: URL) throws -> AIChatManager {
        let data = try Data(contentsOf: url)
        guard let record = Self.importRecord(from: data) else {
            throw ChatSessionImportError.unrecognizedFormat
        }
        let imported = AIChatManager(
            record: ChatSessionRecord(
                id: UUID(), // fresh ID, so importing the same file twice makes two chats
                title: record.title,
                titleIsAutoGenerated: record.titleIsAutoGenerated,
                createdAt: Date(),
                updatedAt: Date(),
                messages: record.messages
            ),
            scope: scope
        )
        register(imported)
        activeManager = imported
        activeSessionID = imported.id
        imported.persist()
        return imported
    }

    /// Writes a conversation (loaded or merely saved on disk) as JSON.
    func exportSession(_ id: UUID, to url: URL) throws {
        let record: ChatSessionRecord
        if let manager = managers[id] {
            record = manager.sessionRecord
        } else if let saved = Self.loadRecord(id: id, directory: recordDirectory) {
            record = saved
        } else {
            throw ChatSessionImportError.unrecognizedFormat
        }
        let data = try Self.encodeRecord(record)
        try data.write(to: url, options: .atomic)
    }

    /// The manager behind a session, when it's loaded (a generating or
    /// approval-waiting session always is) — used for the menu badges.
    func manager(for id: UUID) -> AIChatManager? {
        managers[id]
    }

    /// True when some *other* conversation is still working — shown as a dot
    /// on the session-menu icon so background activity isn't invisible.
    var hasBackgroundActivity: Bool {
        sessions.contains { summary in
            guard summary.id != activeSessionID, let manager = managers[summary.id] else { return false }
            return manager.isGenerating || manager.pendingApproval != nil
        }
    }

    private func activate(_ id: UUID) {
        let manager = managers[id] ?? Self.loadManager(id: id, directory: recordDirectory, scope: scope)
        register(manager)
        activeManager = manager
        activeSessionID = id
    }

    // MARK: - Manager Callback (transcript changed)

    /// The single persistence entry point: every `persist()` in
    /// `AIChatManager` lands here. Refreshes the session's index entry and
    /// rewrites its file — or, for an empty unnamed chat, removes both.
    func chatSessionDidUpdate(_ manager: AIChatManager) {
        guard managers[manager.id] === manager else { return } // dropped or replaced already

        if Self.shouldIndex(messageCount: manager.messages.count, hasCustomTitle: !manager.titleIsAutoGenerated) {
            let summary = manager.summary
            if let index = sessions.firstIndex(where: { $0.id == summary.id }) {
                sessions[index] = summary
            } else {
                sessions.insert(summary, at: 0)
            }
            sessions.sort { $0.updatedAt > $1.updatedAt }
            saveRecord(manager.sessionRecord)
        } else {
            sessions.removeAll { $0.id == manager.id }
            deleteRecord(id: manager.id)
        }
    }

    // MARK: - Storage Layout

    /// Where this scope's sessions live, or nil when they aren't saved
    /// (standalone scope, or the user turned saving off).
    private var recordDirectory: URL? {
        guard AISettingsManager.shared.chatSessionsEnabled else { return nil }
        return Self.sessionsDirectory(for: scope)
    }

    /// Pure scope→directory mapping (no setting consulted), so it's usable
    /// from tests and from `legacyTranscriptURL`.
    static func sessionsDirectory(for scope: LocalToolExecutor.Scope) -> URL? {
        switch scope {
        case .project(let root):
            return ProjectSettingsManager.dotFolderURL(for: root)
                .appendingPathComponent("chat/sessions", isDirectory: true)
        case .notebook(let root):
            let appSupport = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask).first!
            let hash = AppTempDirectoryManager.projectHash(for: root)
            return appSupport
                .appendingPathComponent("TypstEdit/ChatHistory", isDirectory: true)
                .appendingPathComponent(hash, isDirectory: true)
                .appendingPathComponent("sessions", isDirectory: true)
        case .none:
            return nil
        }
    }

    static func indexURL(in directory: URL) -> URL {
        directory.appendingPathComponent("index.json", isDirectory: false)
    }

    static func recordURL(in directory: URL, id: UUID) -> URL {
        directory.appendingPathComponent(id.uuidString + ".json", isDirectory: false)
    }

    /// The pre-sessions storage: one `history.json` per scope.
    static func legacyTranscriptURL(for scope: LocalToolExecutor.Scope) -> URL? {
        switch scope {
        case .project(let root):
            return ProjectSettingsManager.dotFolderURL(for: root)
                .appendingPathComponent("chat/history.json", isDirectory: false)
        case .notebook(let root):
            let appSupport = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask).first!
            let hash = AppTempDirectoryManager.projectHash(for: root)
            return appSupport
                .appendingPathComponent("TypstEdit/ChatHistory", isDirectory: true)
                .appendingPathComponent("\(hash).json", isDirectory: false)
        case .none:
            return nil
        }
    }

    // MARK: - Disk I/O

    private func saveRecord(_ record: ChatSessionRecord) {
        guard let directory = recordDirectory else { return }
        let folder = directory
        if !FileManager.default.fileExists(atPath: folder.path) {
            try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        }
        if let data = try? Self.encodeRecord(record) {
            try? data.write(to: Self.recordURL(in: directory, id: record.id), options: .atomic)
        }
        if let indexData = try? Self.encodeIndex(sessions) {
            try? indexData.write(to: Self.indexURL(in: directory), options: .atomic)
        }
    }

    private func deleteRecord(id: UUID) {
        guard let directory = recordDirectory else { return }
        try? FileManager.default.removeItem(at: Self.recordURL(in: directory, id: id))
        if let indexData = try? Self.encodeIndex(sessions) {
            try? indexData.write(to: Self.indexURL(in: directory), options: .atomic)
        }
    }

    private static func loadRecord(id: UUID, directory: URL?) -> ChatSessionRecord? {
        guard let directory else { return nil }
        guard let data = try? Data(contentsOf: recordURL(in: directory, id: id)) else { return nil }
        return decodeRecord(from: data)
    }

    private static func loadManager(id: UUID, directory: URL?, scope: LocalToolExecutor.Scope) -> AIChatManager {
        if let record = loadRecord(id: id, directory: directory) {
            return AIChatManager(record: record, scope: scope)
        }
        return AIChatManager(scope: scope)
    }

    private static func loadIndex(from url: URL?) -> [ChatSessionSummary] {
        guard let url, let data = try? Data(contentsOf: url) else { return [] }
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        let loaded = (try? decoder.decode([ChatSessionSummary].self, from: data)) ?? []
        return loaded.sorted { $0.updatedAt > $1.updatedAt }
    }

    private static func encodeIndex(_ summaries: [ChatSessionSummary]) throws -> Data {
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .iso8601
        encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
        return try encoder.encode(summaries)
    }

    static func encodeRecord(_ record: ChatSessionRecord) throws -> Data {
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .iso8601
        encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
        return try encoder.encode(record)
    }

    /// Decodes a session file, repairing tool rows that were mid-run when
    /// the app quit (nothing will ever finish them).
    static func decodeRecord(from data: Data) -> ChatSessionRecord? {
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        guard var record = try? decoder.decode(ChatSessionRecord.self, from: data) else { return nil }
        record.messages = Self.normalize(record.messages)
        return record
    }

    /// Decodes the old `[ChatMessage]` history format.
    static func decodeLegacyMessages(from data: Data) -> [ChatMessage]? {
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        guard let loaded = try? decoder.decode([ChatMessage].self, from: data) else { return nil }
        return Self.normalize(loaded)
    }

    /// A tool row still "running" in a saved transcript was interrupted by a
    /// quit or crash — nothing is executing it any more, so its row must not
    /// keep a spinner (or a Stop button) forever.
    static func normalize(_ messages: [ChatMessage]) -> [ChatMessage] {
        var messages = messages
        for index in messages.indices where messages[index].toolStatus == .running {
            messages[index].toolStatus = .cancelled
            messages[index].toolOutput = "Interrupted before it finished (the app closed)."
        }
        return messages
    }

    /// Accepts either the session-record format or the legacy message array.
    static func importRecord(from data: Data) -> ChatSessionRecord? {
        if let record = decodeRecord(from: data) { return record }
        guard let messages = decodeLegacyMessages(from: data), !messages.isEmpty else { return nil }
        return ChatSessionRecord(
            id: UUID(),
            title: fallbackTitle(from: messages),
            titleIsAutoGenerated: true,
            createdAt: messages.first?.timestamp ?? Date(),
            updatedAt: messages.last?.timestamp ?? Date(),
            messages: messages
        )
    }

    // MARK: - Naming & Indexing Rules (pure, unit-tested)

    /// Flattens whitespace and caps the length, so both the message-derived
    /// fallback and the model-written title stay single-line and short.
    static func sanitizedTitle(_ raw: String) -> String {
        let flattened = raw
            .components(separatedBy: .whitespacesAndNewlines)
            .filter { !$0.isEmpty }
            .joined(separator: " ")
        guard flattened.count > 48 else { return flattened }
        return String(flattened.prefix(48))
    }

    /// The title a chat gets from its first user message, before any model
    /// has replied — so the session menu is never full of "Untitled chat".
    static func fallbackTitle(from messages: [ChatMessage]) -> String {
        guard let first = messages.first(where: { $0.role == .user }) else { return "" }
        return sanitizedTitle(first.text)
    }

    /// A safe file name for exporting: punctuation stripped, whitespace
    /// collapsed, length capped.
    static func exportFileName(from title: String) -> String {
        let cleaned = title.filter { character in
            character.isLetter || character.isNumber || character == " " || character == "-" || character == "_"
        }
        let flattened = cleaned.split(separator: " ").joined(separator: " ")
        let trimmed = flattened.trimmingCharacters(in: .whitespaces)
        guard !trimmed.isEmpty else { return "chat" }
        return String(trimmed.prefix(60))
    }

    /// Empty, never-named chats aren't listed or saved — they're the
    /// throwaway slots behind "New Chat" and "Clear history" until the user
    /// actually says something in them.
    static func shouldIndex(messageCount: Int, hasCustomTitle: Bool) -> Bool {
        messageCount > 0 || hasCustomTitle
    }

    // MARK: - Legacy Migration

    /// First open of a scope that still has the old single `history.json`:
    /// import it as one session, then write the index — its presence marks
    /// migration as done, so this never runs (or duplicates) again. The
    /// legacy file itself is left in place.
    private func migrateLegacyIfNeeded() {
        guard let directory = recordDirectory else { return }
        let indexURL = Self.indexURL(in: directory)
        guard !FileManager.default.fileExists(atPath: indexURL.path) else { return }

        let legacyURL = Self.legacyTranscriptURL(for: scope)
        guard let legacyURL,
              let data = try? Data(contentsOf: legacyURL),
              let messages = Self.decodeLegacyMessages(from: data), !messages.isEmpty else {
            // Nothing to carry over — still write the marker index.
            if !FileManager.default.fileExists(atPath: directory.path) {
                try? FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
            }
            if let indexData = try? Self.encodeIndex([]) {
                try? indexData.write(to: indexURL, options: .atomic)
            }
            return
        }

        let record = ChatSessionRecord(
            id: UUID(),
            title: Self.fallbackTitle(from: messages),
            titleIsAutoGenerated: true,
            createdAt: messages.first?.timestamp ?? Date(),
            updatedAt: messages.last?.timestamp ?? Date(),
            messages: messages
        )
        sessions = [ChatSessionSummary(record: record)]
        saveRecord(record)
    }
}
